<template>
  <div class="ym-lifecycle-list" :dir="locale==='ar'?'rtl':'ltr'">
    <div class="desktop">
      <table><colgroup><col class="is-sequence"/><col class="is-event"/><col class="is-work"/><col class="is-workflow"/><col class="is-people"/><col class="is-engagement"/><col class="is-flags"/><col class="is-date"/><col class="is-actions"/></colgroup>
        <thead><tr><th class="is-sequence">#</th><th class="is-event">{{ t.event }}</th><th class="is-work" :aria-sort="ariaSort('title')"><button type="button" @click="$emit('sort','title')">{{ t.work }} {{ indicator('title') }}</button></th><th class="is-workflow" :aria-sort="ariaSort('status')"><button type="button" @click="$emit('sort','status')">{{ t.workflow }} {{ indicator('status') }}</button></th><th class="is-people">{{ t.people }}</th><th class="is-engagement">{{ t.engagement }}</th><th class="is-flags">{{ t.flags }}</th><th class="is-date" :aria-sort="ariaSort('event_at')"><button type="button" @click="$emit('sort','event_at')">{{ t.time }} {{ indicator('event_at') }}</button></th><th class="is-actions">{{ t.actions }}</th></tr></thead>
        <tbody><tr v-for="(item,index) in items" :key="item.id" :class="{attention:item.activity_flags.needs_attention}">
          <td class="is-sequence" dir="ltr">{{ number(sequence(index)) }}</td>
          <td class="is-event"><WorksIndexInfoPopover :label="t.eventInfo" :hint="t.openInfo" :close-label="t.close"><template #trigger><span class="primary"><strong>{{ safe(item.event_label) }}</strong><small>{{ eventHint(item.event_type) }}</small></span></template><dl class="popover"><div><dt>{{ t.id }}</dt><dd dir="ltr">{{ safe(item.id) }}</dd></div><div><dt>{{ t.eventType }}</dt><dd dir="ltr">{{ safe(item.event_type) }}</dd></div><div><dt>{{ t.time }}</dt><dd dir="ltr">{{ dateTime(item.event_at) }}</dd></div><div><dt>{{ t.workId }}</dt><dd dir="ltr">{{ number(item.work_id) }}</dd></div></dl></WorksIndexInfoPopover></td>
          <td class="is-work"><WorksIndexInfoPopover :label="t.workInfo" :hint="t.openInfo" :close-label="t.close"><template #trigger><span class="primary"><strong>{{ safe(item.title) }}</strong><small>{{ media(item.media_type) }}</small></span></template><dl class="popover"><div><dt>{{ t.workId }}</dt><dd dir="ltr">{{ number(item.work_id) }}</dd></div><div><dt>{{ t.title }}</dt><dd>{{ safe(item.title) }}</dd></div><div><dt>{{ t.slug }}</dt><dd dir="ltr">{{ safe(item.slug) }}</dd></div><div><dt>{{ t.media }}</dt><dd>{{ media(item.media_type) }}</dd></div><div><dt>{{ t.category }}</dt><dd dir="ltr">{{ item.category_id===null?t.unavailable:number(item.category_id) }}</dd></div></dl></WorksIndexInfoPopover></td>
          <td class="is-workflow"><WorksIndexInfoPopover :label="t.workflowInfo" :hint="t.openInfo" :close-label="t.close"><template #trigger><span class="primary"><b class="badge">{{ status(item.status) }}</b><small>{{ visibility(item.visibility_status) }}</small></span></template><dl class="popover"><div><dt>{{ t.status }}</dt><dd>{{ status(item.status) }}</dd></div><div><dt>{{ t.visibility }}</dt><dd>{{ visibility(item.visibility_status) }}</dd></div></dl></WorksIndexInfoPopover></td>
          <td class="is-people"><WorksIndexInfoPopover :label="t.peopleInfo" :hint="t.openInfo" :close-label="t.close"><template #trigger><span class="primary"><strong>{{ item.designer?.name||t.unavailable }}</strong><small>{{ item.reviewer?.name||categoryLine(item.category_id) }}</small></span></template><dl class="popover"><div><dt>{{ t.designer }}</dt><dd>{{ person(item.designer) }}</dd></div><div><dt>{{ t.reviewer }}</dt><dd>{{ person(item.reviewer) }}</dd></div><div><dt>{{ t.category }}</dt><dd dir="ltr">{{ item.category_id===null?t.unavailable:number(item.category_id) }}</dd></div></dl></WorksIndexInfoPopover></td>
          <td class="is-engagement"><WorksIndexInfoPopover :label="t.engagementInfo" :hint="t.openInfo" :close-label="t.close"><template #trigger><span class="engagement"><strong><i aria-hidden="true">👁</i><b dir="ltr">{{ number(item.views_count) }}</b><small>{{ t.views }}</small></strong><small class="engagement-details"><span>♥ {{ t.likes }}: <i dir="ltr">{{ number(item.likes_count) }}</i></span><span :class="{ alert: item.reports_count > 0 }">⚑ {{ t.reports }}: <i dir="ltr">{{ number(item.reports_count) }}</i></span></small></span></template><dl class="popover"><div><dt>{{ t.views }}</dt><dd>{{ number(item.views_count) }}</dd></div><div><dt>{{ t.likes }}</dt><dd>{{ number(item.likes_count) }}</dd></div><div><dt>{{ t.reports }}</dt><dd>{{ number(item.reports_count) }}</dd></div></dl></WorksIndexInfoPopover></td>
          <td class="is-flags"><WorksIndexInfoPopover :label="t.flagsInfo" :hint="t.openInfo" :close-label="t.close"><template #trigger><span class="flags"><i v-if="item.activity_flags.needs_attention" :title="t.attention" :aria-label="t.attention">!</i><i v-if="item.activity_flags.is_reported" :title="t.reported" :aria-label="t.reported">⚑</i><small v-if="flagCount(item)===0">{{ t.clear }}</small><b v-if="flagCount(item)>2" dir="ltr">+{{ number(flagCount(item)-2) }}</b></span></template><dl class="popover"><div><dt>{{ t.reviewEvent }}</dt><dd>{{ yesNo(item.activity_flags.is_review_event) }}</dd></div><div><dt>{{ t.visibilityEvent }}</dt><dd>{{ yesNo(item.activity_flags.is_visibility_event) }}</dd></div><div><dt>{{ t.reported }}</dt><dd>{{ yesNo(item.activity_flags.is_reported) }}</dd></div><div><dt>{{ t.promoted }}</dt><dd>{{ yesNo(item.activity_flags.is_promoted) }}</dd></div><div><dt>{{ t.attention }}</dt><dd>{{ yesNo(item.activity_flags.needs_attention) }}</dd></div></dl></WorksIndexInfoPopover></td>
          <td class="is-date"><time :datetime="item.event_at"><strong dir="ltr">{{ date(item.event_at) }}</strong><small dir="ltr">{{ time(item.event_at) }}</small></time></td>
          <td class="is-actions"><button class="details" type="button" :aria-label="`${t.details}: ${safe(item.event_label)}`" :title="t.details" @click="open(item,$event)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.5 12s3.6-6 9.5-6 9.5 6 9.5 6-3.6 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.75"/></svg></button></td>
        </tr></tbody>
      </table>
    </div>
    <div class="mobile"><article v-for="(item,index) in items" :key="item.id"><header><span class="sequence" dir="ltr">#{{ number(sequence(index)) }}</span><div><strong>{{ safe(item.event_label) }}</strong><small>{{ status(item.status) }}</small></div><b v-if="item.activity_flags.needs_attention">!</b></header><dl><div><dt>{{ t.work }}</dt><dd>{{ safe(item.title) }}</dd></div><div><dt>{{ t.time }}</dt><dd dir="ltr">{{ date(item.event_at) }} · {{ time(item.event_at) }}</dd></div><div><dt>{{ t.flags }}</dt><dd>{{ flagCount(item) ? number(flagCount(item)) : t.clear }}</dd></div></dl><footer><span>{{ visibility(item.visibility_status) }}</span><button class="details" type="button" :aria-label="`${t.details}: ${safe(item.event_label)}`" :title="t.details" @click="open(item,$event)">{{ t.details }}</button></footer></article></div>
  </div>
</template>
<script setup lang="ts">
import{computed}from'vue';import WorksIndexInfoPopover from'~/components/works/index/WorksIndexInfoPopover.vue';import{formatYmDate,formatYmDateTime,formatYmNumber,toLatinDigits}from'~/utils/ymFormatting'
type Locale='ar'|'en';type SortKey='event_at'|'work_id'|'title'|'status'|'reports_count';type Direction='asc'|'desc';interface User{id:number;name:string}interface Item{id:string;work_id:number;event_type:string;event_label:string;event_at:string;title:string;slug:string;status:string;visibility_status:'public'|'hidden';media_type:string|null;designer:User|null;reviewer:User|null;category_id:number|null;reports_count:number;views_count:number;likes_count:number;activity_flags:{is_review_event:boolean;is_visibility_event:boolean;is_reported:boolean;is_promoted:boolean;needs_attention:boolean}}
const props=defineProps<{items:Item[];locale:Locale;sort:SortKey;direction:Direction;currentPage:number;perPage:number}>();const emit=defineEmits<{sort:[key:SortKey];details:[item:Item,trigger:HTMLElement|null]}>();const copy={ar:{event:'الحدث',work:'العمل',workflow:'سير العمل',people:'الأشخاص والتصنيف',engagement:'التفاعل',flags:'المؤشرات',time:'وقت الحدث',actions:'الإجراءات',eventInfo:'تفاصيل الحدث',workInfo:'تفاصيل العمل',workflowInfo:'تفاصيل سير العمل',peopleInfo:'تفاصيل الأشخاص والتصنيف',engagementInfo:'تفاصيل التفاعل',flagsInfo:'تفاصيل المؤشرات',openInfo:'عرض المعلومات',close:'إغلاق',id:'المعرّف',eventType:'نوع الحدث',workId:'معرّف العمل',title:'العنوان',slug:'المعرّف النصي',media:'الوسائط',category:'التصنيف',status:'الحالة',visibility:'الظهور',designer:'المصمم',reviewer:'المراجع',views:'المشاهدات',likes:'الإعجابات',reports:'البلاغات',reviewEvent:'حدث مراجعة',visibilityEvent:'حدث ظهور',reported:'عليه بلاغات',promoted:'مروّج',attention:'يحتاج انتباهًا',details:'عرض التفاصيل',unavailable:'غير متاح',clear:'سليم',yes:'نعم',no:'لا'},en:{event:'Event',work:'Work',workflow:'Workflow',people:'People and category',engagement:'Engagement',flags:'Flags',time:'Event time',actions:'Actions',eventInfo:'Event details',workInfo:'Work details',workflowInfo:'Workflow details',peopleInfo:'People and category details',engagementInfo:'Engagement details',flagsInfo:'Flag details',openInfo:'Open information',close:'Close',id:'ID',eventType:'Event type',workId:'Work ID',title:'Title',slug:'Text identifier',media:'Media',category:'Category',status:'Status',visibility:'Visibility',designer:'Designer',reviewer:'Reviewer',views:'Views',likes:'Likes',reports:'Reports',reviewEvent:'Review event',visibilityEvent:'Visibility event',reported:'Reported',promoted:'Promoted',attention:'Needs attention',details:'View details',unavailable:'Unavailable',clear:'Clear',yes:'Yes',no:'No'}}as const;const t=computed(()=>copy[props.locale])
const arStatus:Record<string,string>={draft:'مسودة',submitted:'مرسل',in_review:'قيد المراجعة',changes_requested:'تعديلات مطلوبة',approved:'معتمد',published:'منشور',rejected:'مرفوض',hidden:'مخفي',archived:'مؤرشف'};function safe(v:string|number){return toLatinDigits(v)}function number(v:number){return formatYmNumber(Number.isFinite(v)?v:0,props.locale)}function sequence(i:number){return((props.currentPage-1)*props.perPage)+i+1}function status(v:string){return props.locale==='ar'?(arStatus[v]||safe(v)):safe(v.replaceAll('_',' '))}function visibility(v:string){return v==='public'?(props.locale==='ar'?'عام':'Public'):(props.locale==='ar'?'مخفي':'Hidden')}function media(v:string|null){if(v==='image')return props.locale==='ar'?'صورة':'Image';if(v==='video')return props.locale==='ar'?'فيديو':'Video';return v?safe(v):t.value.unavailable}function person(v:User|null){return v?`${safe(v.name)} #${number(v.id)}`:t.value.unavailable}function categoryLine(v:number|null){return v===null?t.value.unavailable:`${t.value.category}: ${number(v)}`}function yesNo(v:boolean){return v?t.value.yes:t.value.no}function eventHint(v:string){const map:Record<string,string>={created:'إنشاء العمل',updated:'تحديث العمل',submitted:'إرسال للمراجعة',reviewed:'مراجعة العمل',approved:'اعتماد العمل',published:'نشر العمل',rejected:'رفض العمل',hidden:'إخفاء العمل',archived:'أرشفة العمل'};return props.locale==='ar'?(map[v]||safe(v)):safe(v.replaceAll('_',' '))}function date(v:string){return formatYmDate(v,props.locale)}function time(v:string){return formatYmDateTime(v,props.locale).split('·').at(-1)?.trim()||t.value.unavailable}function dateTime(v:string){return formatYmDateTime(v,props.locale)}function flagCount(i:Item){return Object.values(i.activity_flags).filter(Boolean).length}function indicator(k:SortKey){return props.sort!==k?'↕':props.direction==='asc'?'↑':'↓'}function ariaSort(k:SortKey){return props.sort!==k?'none':props.direction==='asc'?'ascending':'descending'}function open(i:Item,e:MouseEvent){emit('details',i,e.currentTarget instanceof HTMLElement?e.currentTarget:null)}
</script>
<style scoped>
.ym-lifecycle-list{min-width:0}.desktop{overflow:hidden}table{width:100%;table-layout:fixed;border-collapse:separate;border-spacing:0}col.is-sequence{width:42px}col.is-event{width:15%}col.is-work{width:auto}col.is-workflow{width:14%}col.is-people{width:16%}col.is-engagement{width:11%}col.is-flags{width:12%}col.is-date{width:145px}col.is-actions{width:58px}th,td{box-sizing:border-box;height:72px;border:0;border-bottom:1px solid var(--ym-soft-border);padding:8px;text-align:start;vertical-align:middle;background:transparent;font-size:13px}thead{background:var(--ym-table-header-bg)}th{height:50px;color:var(--ym-text);font-size:12px;font-weight:850;text-align:center}th button{border:0;background:transparent;color:inherit;font:inherit;cursor:pointer}th:not(:last-child),td:not(:last-child){border-inline-end:1px solid color-mix(in srgb,var(--ym-card-border) 25%,transparent)}tbody tr{background:color-mix(in srgb,var(--ym-control-bg) 94%,transparent)}tbody tr:hover{background:color-mix(in srgb,var(--ym-control-bg) 88%,#0e7490 12%)}tbody tr.attention td.is-event{box-shadow:inset 2px 0 #f59e0b}.is-sequence{width:42px;min-width:42px;max-width:42px;padding-inline:4px;text-align:center;font-weight:600;font-variant-numeric:tabular-nums}.is-date,.is-flags,.is-actions{text-align:center}td :deep(.ym-floating-overlay){width:100%}.primary,.engagement{display:grid;min-width:0;gap:3px}.primary strong,.primary small,.engagement small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.primary strong{color:var(--ym-text);font-size:13.5px}.primary small,.engagement small{color:var(--ym-muted);font-size:11.5px}.badge{width:max-content;max-width:100%;overflow:hidden;border:1px solid var(--ym-soft-border);border-radius:999px;padding:3px 7px;color:var(--ym-text);background:var(--ym-control-bg);font-size:11px;text-overflow:ellipsis;white-space:nowrap}.engagement strong{color:var(--ym-text);font-size:16px}.engagement i{font-style:normal}.flags{display:flex;align-items:center;justify-content:center;gap:4px}.flags i{display:grid;width:24px;height:24px;place-items:center;border-radius:50%;color:#fff;background:#9f1239;font-style:normal;font-weight:900}.flags i+i{background:#92400e}.flags small{color:var(--ym-muted)}.flags b{color:var(--ym-text);font-size:11px}.is-date time{display:grid;gap:2px}.is-date strong{color:var(--ym-text);font-size:12.5px}.is-date small{color:var(--ym-muted);font-size:11.5px}.details{display:grid;width:38px;height:38px;margin:auto;place-items:center;border:1px solid var(--ym-control-border);border-radius:10px;color:#fff;background:#0e7490;font-weight:850;cursor:pointer}.details:focus-visible,th button:focus-visible{outline:3px solid color-mix(in srgb,#0e7490 35%,transparent);outline-offset:2px}.popover{display:grid;gap:7px;margin:0}.popover>div{display:grid;gap:2px;border-bottom:1px solid var(--ym-soft-border);padding-bottom:7px}.popover>div:last-child{border:0;padding:0}.popover dt{color:var(--ym-muted);font-size:11.5px}.popover dd{margin:0;color:var(--ym-text);font-size:12.5px;overflow-wrap:anywhere}.mobile{display:none;gap:9px}.mobile article{display:grid;gap:9px;border:1px solid var(--ym-card-border);border-radius:14px;padding:11px;background:var(--ym-control-bg)}.mobile header,.mobile footer{display:flex;align-items:center;justify-content:space-between;gap:8px}.mobile header>div{display:grid;min-width:0;flex:1}.mobile header strong,.mobile header small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.sequence{display:grid;width:26px;height:26px;place-items:center;border-radius:8px;background:var(--ym-input-bg);font-size:11px;font-weight:700}.mobile header>b{display:grid;width:25px;height:25px;place-items:center;border-radius:50%;color:#fff;background:#9f1239}.mobile dl{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;margin:0}.mobile dt{color:var(--ym-muted);font-size:11px}.mobile dd{margin:2px 0 0;color:var(--ym-text);font-size:12px}.mobile footer{border-top:1px solid var(--ym-soft-border);padding-top:8px}@media(max-width:900px){.desktop{display:none}.mobile{display:grid}}@media(max-width:600px){.mobile dl{grid-template-columns:1fr}}
</style>
<style scoped>
col.is-engagement{width:13%}
col.is-flags{width:10%}
.engagement strong{display:flex;align-items:baseline;justify-content:center;gap:4px}
.engagement strong>i{align-self:center;font-size:13px}
.engagement strong>b{color:var(--ym-text);font-size:17px;font-weight:900}
.engagement strong>small{color:var(--ym-muted);font-size:10.5px;font-weight:750}
.engagement .engagement-details{display:grid;gap:2px;white-space:normal}
.engagement-details span{display:flex;align-items:center;justify-content:space-between;gap:4px}
