.details{transition:border-color 150ms ease,background 150ms ease,box-shadow 150ms ease,transform 150ms ease}
.details:hover{border-color:#22d3ee;background:#0c829f;box-shadow:0 5px 14px rgba(14,116,144,.24);transform:translateY(-1px)}
:global(.ym-dashboard-light) .ym-lifecycle-list thead{background:color-mix(in srgb,var(--ym-table-header-bg) 72%,#d9ebe8)}
:global(.ym-dashboard-light) .ym-lifecycle-list th{border-bottom-color:color-mix(in srgb,var(--ym-control-border) 65%,#64748b)}
:global(.ym-dashboard-light) .ym-lifecycle-list td{border-bottom-color:color-mix(in srgb,var(--ym-soft-border) 58%,#94a3b8)}
:global(.ym-dashboard-light) .primary small,
:global(.ym-dashboard-light) .is-date small,
:global(.ym-dashboard-light) .engagement small,
:global(.ym-dashboard-light) .flags small{color:color-mix(in srgb,var(--ym-muted) 64%,#334155)}
